        );
        // 先頭行・最終行では動かない
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(0),
                Movement::Line,
                Direction::Backward
            ),
            Selection::point(0)
        );
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(8),
                Movement::Line,
                Direction::Forward
            ),
            Selection::point(8)
        );
    }

    #[test]
    fn move_word_basic() {
        let doc = Document::from("hello world foo");
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(0),
                Movement::Word,
                Direction::Forward
            ),
            Selection::point(6)
        );
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(6),
                Movement::Word,
                Direction::Forward
            ),
            Selection::point(12)
        );
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(12),
                Movement::Word,
                Direction::Backward
            ),
            Selection::point(6)
        );
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(6),
                Movement::Word,
                Direction::Backward
            ),
            Selection::point(0)
        );
    }

    #[test]
    fn move_word_unicode() {
        // 日本語は is_alphanumeric なので1語として扱われる
        let doc = Document::from("こんにちは世界");
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(0),
                Movement::Word,
                Direction::Forward
            ),
            Selection::point(7)
        );
        let mixed = Document::from("hello 世界");
        assert_eq!(
            move_selection(
                &mixed,
                &Selection::point(0),
                Movement::Word,
                Direction::Forward
            ),
            Selection::point(6)
        );
    }

    #[test]
    fn move_word_at_boundaries() {
        let single = Document::from("hello");
        assert_eq!(
            move_selection(
                &single,
                &Selection::point(0),
                Movement::Word,
                Direction::Forward
            ),
            Selection::point(5)
        );
        let empty = Document::new();
        assert_eq!(
            move_selection(
                &empty,
                &Selection::point(0),
                Movement::Word,
                Direction::Forward
            ),
            Selection::point(0)
        );
    }

    #[test]
    fn extend_word_keeps_anchor() {
        let doc = Document::from("hello world");
        // 先頭から次の単語先頭（前の空白を含む）まで拡張される
        assert_eq!(
            extend_selection(
                &doc,
                &Selection::point(0),
                Movement::Word,
                Direction::Forward
            ),
