    write_half: &mut OwnedWriteHalf,
    reader: &mut BufReader<tokio::net::unix::OwnedReadHalf>,
    command: Command,
) -> std::io::Result<StateSnapshot> {
    let mut line = serde_json::to_string(&command).expect("command はシリアライズ可能");
